CREATE OR REPLACE FUNCTION app.css_rule_preludes(p_css text)
 RETURNS text[]
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  preludes text[] := ARRAY[]::text[];
  current text := '';
  token text[];
  part text;
BEGIN
  IF p_css IS NULL THEN RETURN preludes; END IF;
  FOR token IN SELECT regexp_matches(p_css,
    $tokens$\\.|"(?:[^"\\]|\\.)*"|'(?:[^'\\]|\\.)*'|[{}]|[^{}"'\\]+|["'\\]$tokens$, 'g')
  LOOP
    part := token[1];
    IF part = '"' OR part = '''' THEN RETURN NULL; END IF;
    IF part = '{' THEN
      preludes := array_append(preludes, current);
      current := '';
    ELSIF part = '}' THEN
      current := '';
    ELSE
      current := current || part;
    END IF;
  END LOOP;
  RETURN preludes;
END
$function$
